/**
 * DiffReviewTailNode — renderer for our own `diff-review-tail` chat node kind.
 *
 * Registered under the keyed slot `conversation.chat.node` with key
 * `diff-review-tail`; receives the chat node via the owner share and renders
 * the Codex-style file-change card for that turn.
 */
import type { ReactElement } from 'react'
import type { InjectFace, PropsRuntime } from '@deepseek-ai/dsh-client-ui-slots'
import { TurnDiffCard, type TurnDiffCardProps } from './TurnDiffCard.tsx'

interface DiffReviewTailNodeData {
  turn?: number
}

type Props = PropsRuntime<'conversation.chat.node'> &
  InjectFace<Pick<TurnDiffCardProps, 'openReview'>> & {
    node?: { data?: DiffReviewTailNodeData }
  }

export function DiffReviewTailNode({ node, sessionId, openReview }: Props): ReactElement | null {
  const turn = node?.data?.turn
  if (typeof turn !== 'number') return null
  return <TurnDiffCard sessionId={sessionId} turn={turn} openReview={openReview} />
}
