/** Client-side wire types for the dsh-diff-review host API. */

export interface FileChangeSummary {
  path: string
  plus: number
  minus: number
  diff: string
}

export interface TurnChangeSummary {
  turn: number
  files: FileChangeSummary[]
}

export interface TurnResponse {
  ok: boolean
  files?: FileChangeSummary[]
}

export interface SessionResponse {
  ok: boolean
  turns?: TurnChangeSummary[]
}

export async function fetchTurn(sessionId: string, turn: number): Promise<FileChangeSummary[]> {
  const url = `/api/dsh-diff-review/turn?session=${encodeURIComponent(sessionId)}&turn=${encodeURIComponent(String(turn))}`
  const response = await fetch(url)
  if (!response.ok) return []
  const body = (await response.json()) as TurnResponse
  return body.ok ? body.files ?? [] : []
}

export async function fetchSession(sessionId: string): Promise<TurnChangeSummary[]> {
  const url = `/api/dsh-diff-review/session?session=${encodeURIComponent(sessionId)}`
  const response = await fetch(url)
  if (!response.ok) return []
  const body = (await response.json()) as SessionResponse
  return body.ok ? body.turns ?? [] : []
}

export function shortPath(path: string): string {
  const parts = path.split(/[\\/]/)
  return parts[parts.length - 1] ?? path
}
