/**
 * TurnDiffCard — Codex-style per-turn file-change card.
 *
 * Presentational component: receives a numeric turn and renders the card by
 * fetching that turn's change summary from the host API.
 */
import { useEffect, useState, type CSSProperties, type ReactElement } from 'react'
import { fetchTurn, shortPath, type FileChangeSummary } from './types.ts'

export interface TurnDiffCardProps {
  sessionId: string
  turn: number
  openReview: (fileKey?: string) => void
}

const MAX_VISIBLE = 3

function FileIcon(): ReactElement {
  return (
    <svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <path d="M6 3h9l4 4v14H6V3Z" stroke="currentColor" strokeWidth="1.7" strokeLinejoin="round" />
      <path d="M14 3v5h5M9 13h6M9 17h6" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

function CopyIcon(): ReactElement {
  return (
    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" aria-hidden="true">
      <rect x="9" y="9" width="11" height="11" rx="2" stroke="currentColor" strokeWidth="1.7" />
      <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" />
    </svg>
  )
}

export function TurnDiffCard({ sessionId, turn, openReview }: TurnDiffCardProps): ReactElement | null {
  const [files, setFiles] = useState<FileChangeSummary[] | null>(null)
  const [expanded, setExpanded] = useState(false)

  useEffect(() => {
    let alive = true
    const load = async (): Promise<void> => {
      const next = await fetchTurn(sessionId, turn)
      if (alive) setFiles(next)
    }
    void load()
    // Poll briefly: the host may still be processing the last tool calls.
    const timer = setInterval(() => void load(), 1500)
    return () => {
      alive = false
      clearInterval(timer)
    }
  }, [sessionId, turn])

  if (files === null || files.length === 0) return null

  const plus = files.reduce((sum, file) => sum + file.plus, 0)
  const minus = files.reduce((sum, file) => sum + file.minus, 0)
  const visibleFiles = expanded ? files : files.slice(0, MAX_VISIBLE)
  const hiddenCount = files.length - visibleFiles.length

  const copySummary = async (): Promise<void> => {
    const text = files.map((file) => `${file.path} +${file.plus} -${file.minus}`).join('\n')
    try {
      await navigator.clipboard?.writeText(text)
    } catch {
      // Clipboard is best-effort.
    }
  }

  return (
    <div style={cardStyle}>
      <div style={headStyle}>
        <span style={headIconStyle}><FileIcon /></span>
        <span style={titleStyle}>已编辑 {files.length} 个文件</span>
        <span style={totalStyle}>
          <span style={plusStyle}>+{plus}</span>{' '}
          <span style={minusStyle}>−{minus}</span>
        </span>
        <div style={headActionsStyle}>
          <button type="button" style={ghostButtonStyle} title="复制文件改动摘要" onClick={() => void copySummary()}>
            <CopyIcon />
          </button>
          <button type="button" style={primaryButtonStyle} onClick={() => openReview()}>
            审核
          </button>
        </div>
      </div>

      <div style={listStyle}>
        {visibleFiles.map((file) => (
          <button key={file.path} type="button" style={fileRowStyle} title={`在审阅视图中查看 ${file.path}`} onClick={() => openReview(`${turn}:${file.path}`)}>
            <span style={fileNameStyle}>{shortPath(file.path)}</span>
            <span style={fileStatStyle}>
              <span style={plusStyle}>+{file.plus}</span>{' '}
              <span style={minusStyle}>−{file.minus}</span>
            </span>
          </button>
        ))}
      </div>

      {hiddenCount > 0 && (
        <button type="button" style={moreButtonStyle} onClick={() => setExpanded(true)}>
          再显示 {hiddenCount} 个文件
        </button>
      )}
    </div>
  )
}

const cardStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: 8,
  width: '100%',
  maxWidth: 'var(--dsh-composer-card-max-width, 780px)',
  margin: '10px auto 0',
  padding: '10px 12px 12px',
  borderRadius: 12,
  border: '1px solid var(--dsw-alias-border-l2, rgba(196, 211, 232, 0.16))',
  background: 'var(--dsw-alias-bg-layer-1, #171f2b)',
  color: 'var(--dsw-alias-label-primary, #f2f6fc)',
  fontFamily: 'ui-monospace, "Cascadia Mono", "SFMono-Regular", Consolas, monospace',
  fontSize: 12,
  lineHeight: 1.5,
  boxSizing: 'border-box',
}

const headStyle: CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  gap: 8,
}

const headIconStyle: CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  color: 'var(--dsw-alias-brand-primary, #8ec5ff)',
}

const titleStyle: CSSProperties = {
  color: 'var(--dsw-alias-label-primary, #f2f6fc)',
  fontSize: 13,
  fontWeight: 520,
}

const totalStyle: CSSProperties = {
  display: 'inline-flex',
  gap: 6,
  fontVariantNumeric: 'tabular-nums',
  fontWeight: 480,
}

const plusStyle: CSSProperties = {
  color: 'var(--dsw-alias-state-success-primary, #78dda0)',
}

const minusStyle: CSSProperties = {
  color: 'var(--dsw-alias-state-error-primary, #ff8592)',
}

const headActionsStyle: CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  gap: 6,
  marginLeft: 'auto',
}

const ghostButtonStyle: CSSProperties = {
  display: 'inline-grid',
  placeItems: 'center',
  width: 26,
  height: 26,
  padding: 0,
  borderRadius: 7,
  border: '1px solid var(--dsw-alias-border-l2, rgba(196, 211, 232, 0.16))',
  background: 'transparent',
  color: 'var(--dsw-alias-label-secondary, #9daabd)',
  cursor: 'pointer',
}

const primaryButtonStyle: CSSProperties = {
  height: 26,
  padding: '0 12px',
  borderRadius: 7,
  border: '1px solid color-mix(in srgb, var(--dsw-alias-brand-primary, #8ec5ff) 55%, transparent)',
  background: 'color-mix(in srgb, var(--dsw-alias-brand-primary, #8ec5ff) 12%, transparent)',
  color: 'var(--dsw-alias-brand-primary, #8ec5ff)',
  cursor: 'pointer',
  fontFamily: 'inherit',
  fontSize: 12,
  fontWeight: 520,
}

const listStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: 4,
}

const fileRowStyle: CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  gap: 10,
  width: '100%',
  padding: '6px 9px',
  borderRadius: 8,
  border: '1px solid var(--dsw-alias-border-l2, rgba(196, 211, 232, 0.16))',
  background: 'var(--dsw-alias-bg-layer-2, #101722)',
  color: 'var(--dsw-alias-label-primary, #f2f6fc)',
  cursor: 'pointer',
  fontFamily: 'inherit',
  fontSize: 12,
  textAlign: 'left',
}

const fileNameStyle: CSSProperties = {
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap',
  minWidth: 0,
}

const fileStatStyle: CSSProperties = {
  marginLeft: 'auto',
  flex: 'none',
  display: 'inline-flex',
  gap: 6,
  fontVariantNumeric: 'tabular-nums',
}

const moreButtonStyle: CSSProperties = {
  alignSelf: 'flex-start',
  padding: '2px 6px',
  borderRadius: 6,
  border: 'none',
  background: 'transparent',
  color: 'var(--dsw-alias-label-tertiary, #718096)',
  cursor: 'pointer',
  fontFamily: 'inherit',
  fontSize: 12,
}
