/**
 * ReviewSidebarTab — the dsh-better-sidebar "审阅" tab.
 *
 * Lists every turn that touched files in the current session. Clicking a file
 * expands the diff computed by the host (self-contained, git-free — works for
 * files outside the session repository and for untracked files too).
 */
import { useEffect, useState, type CSSProperties, type ReactElement } from 'react'
import type { TabComponentProps } from 'dsh-better-sidebar'
import { fetchSession, shortPath, type TurnChangeSummary } from './types.ts'

function stripPatchHeader(diff: string): string {
  return diff.replace(/^={3,}\n/, '')
}

/** Codex-style colored unified-diff viewer: green added lines, red removed lines. */
function DiffView({ diff }: { diff: string }): ReactElement {
  const lines = stripPatchHeader(diff).split('\n')
  return (
    <div style={diffBoxStyle}>
      {lines.map((line, index) => {
        let lineStyle = diffLineStyle
        if (line.startsWith('+') && !line.startsWith('+++')) lineStyle = diffAddLineStyle
        else if (line.startsWith('-') && !line.startsWith('---')) lineStyle = diffDelLineStyle
        else if (line.startsWith('@@')) lineStyle = diffHunkLineStyle
        return (
          <div key={index} style={lineStyle}>
            {line === '' ? '\u00a0' : line}
          </div>
        )
      })}
    </div>
  )
}

/** Pending file key (`turn:path`) to auto-expand once the review tab is mounted/visible. */
let pendingReviewFile: string | null = null

/** Unique expansion key for one file row across turns (same path may appear in several turns). */
function fileKeyOf(turn: number, path: string): string {
  return `${turn}:${path}`
}

/**
 * Ask the review tab (wherever mounted) to expand a specific file's diff.
 * Called by the conversation card before opening the sidebar review tab.
 * The key is `turn:path` so same-named files in different turns stay distinct.
 */
export function requestReviewFile(key: string): void {
  pendingReviewFile = key
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('dsh-diff-review:open-file', { detail: key }))
  }
}

export function ReviewSidebarTab({ scope, visible }: TabComponentProps): ReactElement {
  const sessionId = scope.sessionId
  const [turns, setTurns] = useState<TurnChangeSummary[]>([])
  const [loading, setLoading] = useState(true)
  const [openFile, setOpenFile] = useState<string | null>(null)

  useEffect(() => {
    if (!visible) return undefined
    let alive = true
    const load = async (): Promise<void> => {
      const next = await fetchSession(sessionId)
      if (alive) {
        // Review view reads top-to-bottom: oldest turn first.
        setTurns([...next].sort((a, b) => a.turn - b.turn))
        setLoading(false)
      }
    }
    void load()
    const timer = setInterval(() => void load(), 3000)
    return () => {
      alive = false
      clearInterval(timer)
    }
  }, [visible, sessionId])

  // Live request from the conversation card: expand this file's diff.
  useEffect(() => {
    const onOpen = (event: Event): void => {
      const key = (event as CustomEvent<string>).detail
      if (typeof key === 'string' && key !== '') setOpenFile(key)
    }
    window.addEventListener('dsh-diff-review:open-file', onOpen)
    return () => window.removeEventListener('dsh-diff-review:open-file', onOpen)
  }, [])

  // If a file was requested before this tab mounted, honor it once visible.
  useEffect(() => {
    if (visible && pendingReviewFile !== null) {
      setOpenFile(pendingReviewFile)
      pendingReviewFile = null
    }
  }, [visible])

  const toggle = (key: string): void => {
    setOpenFile((current) => (current === key ? null : key))
  }

  if (loading) {
    return <div style={emptyStyle}>正在读取文件改动…</div>
  }

  if (turns.length === 0) {
    return <div style={emptyStyle}>本轮会话还没有文件改动记录。</div>
  }

  const totalFiles = turns.reduce((sum, turn) => sum + turn.files.length, 0)
  const totalPlus = turns.reduce((sum, turn) => sum + turn.files.reduce((s, f) => s + f.plus, 0), 0)
  const totalMinus = turns.reduce((sum, turn) => sum + turn.files.reduce((s, f) => s + f.minus, 0), 0)

  return (
    <div style={rootStyle}>
      <div style={headStyle}>
        <span style={titleStyle}>文件改动审阅</span>
        <span style={summaryStyle}>{totalFiles} 文件 · +{totalPlus} −{totalMinus}</span>
      </div>
      {turns.map((turn) => (
        <section key={turn.turn} style={turnStyle}>
          <header style={turnHeaderStyle}>第 {turn.turn} 轮 · {turn.files.length} 个文件</header>
          {turn.files.map((file) => {
            const openKey = fileKeyOf(turn.turn, file.path)
            return (
              <div key={openKey} style={fileBlockStyle}>
                <button type="button" style={fileRowStyle} title={file.path} onClick={() => toggle(openKey)}>
                  <span style={filePathStyle}>{file.path}</span>
                  <span style={fileStatStyle}>
                    <span style={plusStyle}>+{file.plus}</span>{' '}
                    <span style={minusStyle}>−{file.minus}</span>
                  </span>
                </button>
                {openFile === openKey && <DiffView diff={file.diff} />}
              </div>
            )
          })}
        </section>
      ))}
    </div>
  )
}

const rootStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: 10,
  padding: 12,
  overflowY: 'auto',
  height: '100%',
  boxSizing: 'border-box',
  fontFamily: 'ui-monospace, "Cascadia Mono", "SFMono-Regular", Consolas, monospace',
  fontSize: 12,
  lineHeight: 1.5,
}

const headStyle: CSSProperties = {
  display: 'flex',
  alignItems: 'baseline',
  gap: 10,
}

const titleStyle: CSSProperties = {
  color: 'var(--dsw-alias-label-primary, #f2f6fc)',
  fontSize: 14,
  fontWeight: 520,
}

const summaryStyle: CSSProperties = {
  color: 'var(--dsw-alias-label-tertiary, #718096)',
  fontVariantNumeric: 'tabular-nums',
}

const turnStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: 6,
}

const turnHeaderStyle: CSSProperties = {
  color: 'var(--dsw-alias-label-secondary, #9daabd)',
  fontSize: 12,
  fontWeight: 480,
}

const fileBlockStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: 0,
}

const fileRowStyle: CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  gap: 10,
  width: '100%',
  padding: '7px 9px',
  borderRadius: 8,
  border: '1px solid var(--dsw-alias-border-l2, rgba(196, 211, 232, 0.16))',
  background: 'var(--dsw-alias-bg-layer-1, #171f2b)',
  color: 'var(--dsw-alias-label-primary, #f2f6fc)',
  cursor: 'pointer',
  fontFamily: 'inherit',
  fontSize: 12,
  textAlign: 'left',
}

const filePathStyle: CSSProperties = {
  overflow: 'hidden',
  textOverflow: 'ellipsis',
  whiteSpace: 'nowrap',
  minWidth: 0,
}

const fileStatStyle: CSSProperties = {
  marginLeft: 'auto',
  flex: 'none',
  display: 'inline-flex',
  gap: 6,
  fontVariantNumeric: 'tabular-nums',
}

const plusStyle: CSSProperties = {
  color: 'var(--dsw-alias-state-success-primary, #78dda0)',
}

const minusStyle: CSSProperties = {
  color: 'var(--dsw-alias-state-error-primary, #ff8592)',
}

const diffBoxStyle: CSSProperties = {
  margin: '4px 0 0',
  borderRadius: 8,
  border: '1px solid var(--dsw-alias-border-l2, rgba(196, 211, 232, 0.16))',
  background: 'var(--dsw-alias-bg-layer-2, #101722)',
  overflowX: 'auto',
  padding: '6px 0',
}

const diffLineStyle: CSSProperties = {
  padding: '0 10px',
  fontSize: 11,
  lineHeight: 1.6,
  whiteSpace: 'pre',
  color: 'var(--dsw-alias-label-secondary, #9daabd)',
  fontFamily: 'inherit',
}

const diffAddLineStyle: CSSProperties = {
  ...diffLineStyle,
  background: 'rgba(70, 200, 120, 0.16)',
  color: 'var(--dsw-alias-state-success-primary, #78dda0)',
}

const diffDelLineStyle: CSSProperties = {
  ...diffLineStyle,
  background: 'rgba(255, 100, 110, 0.16)',
  color: 'var(--dsw-alias-state-error-primary, #ff8592)',
}

const diffHunkLineStyle: CSSProperties = {
  ...diffLineStyle,
  background: 'rgba(142, 197, 255, 0.10)',
  color: 'var(--dsw-alias-brand-primary, #8ec5ff)',
}

const emptyStyle: CSSProperties = {
  padding: '24px 12px',
  color: 'var(--dsw-alias-label-tertiary, #718096)',
  textAlign: 'center',
}
