/**
 * @dsh-external/dsh-diff-review — browser half.
 *
 * - Own conversation node kind `diff-review-tail`: built at every `turn/end`,
 *   rendered through the keyed `conversation.chat.node` slot as a Codex-style
 *   file-change card at the tail of the turn that touched files.
 * - `dsh-better-sidebar` review tab: session-wide review list; clicking a
 *   file expands the host-computed diff inline (git-free). Optional service.
 */
import { createElement, type ReactNode } from 'react'
import type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client'
// Type-only side-effect imports: SlotMap augmentations for the slots below.
import type {} from '@deepseek-ai/dsh-client-ui-slots'
import type {} from '@deepseek-ai/dsh-client-ui-conversation/client'
// Pulls in the ctx.betterSidebar Context augmentation.
import type {} from 'dsh-better-sidebar'
import { ReviewSidebarTab, requestReviewFile } from './ReviewSidebarTab.tsx'
import { DiffReviewTailNode } from './DiffReviewTailNode.tsx'

/** Required services for this browser plugin (sidebar is optional). */
export const inject = ['slots']

const TAIL_KIND = 'diff-review-tail'

export function apply(ctx: ClientContext): void {
  // Optional service read via ctx.get: Cordis forbids property access for
  // services that are not declared in `inject` (it throws at runtime).
  const betterSidebar = ctx.get('betterSidebar') as
    | { openTab(seed: unknown, scope?: unknown): void; registerTab(descriptor: unknown): () => void }
    | undefined

  const openReview = (fileKey?: string): void => {
    if (betterSidebar === undefined) return
    if (fileKey !== undefined) requestReviewFile(fileKey)
    betterSidebar.openTab({ type: '@dsh-external/dsh-diff-review:review' })
  }

  const face = { openReview }

  try {
    ctx.slots.register({
      name: 'conversation.chat.node',
      key: TAIL_KIND,
      inject: () => face,
    }, DiffReviewTailNode)
  } catch (error) {
    console.error('dsh-diff-review: failed to register diff-review-tail node renderer', error)
  }

  // Own conversation definition: one chat node per completed turn, anchored
  // right after turn/end so it appears at the tail of that turn.
  const conversationEvents = ctx.get('conversationEvents') as
    | { register(definition: unknown): () => void }
    | undefined
  if (conversationEvents !== undefined) {
    try {
      const dispose = conversationEvents.register({
        kind: TAIL_KIND,
        target: 'chat',
        match: (event: { type: string; data?: { turn?: unknown } }) => {
          if (event.type === 'turn/end' && typeof event.data?.turn === 'number') {
            return { id: String(event.data.turn), role: 'start' as const }
          }
          return null
        },
        start: (_context: unknown, match: { event: { type: string } }): { end: typeof match } => {
          if (match.event.type !== 'turn/end') throw new Error('diff-review-tail start requires turn/end')
          return { end: match }
        },
        buildViewNode: (context: {
          key: string
          id: string
          state?: { end?: { event?: { seq?: number; time?: number; data?: { turn?: number } } } }
        }) => {
          const end = context.state?.end
          const turn = end?.event?.data?.turn
          if (end?.event?.seq === undefined || typeof turn !== 'number') return null
          return {
            key: context.key,
            kind: TAIL_KIND,
            id: context.id,
            target: 'chat',
            anchorSeq: end.event.seq + 0.5,
            location: { kind: 'unresolved' },
            visibility: 'visible',
            data: { turn, seq: end.event.seq, time: end.event.time ?? 0 },
          }
        },
        publication: (match: { event: { type: string } }): 'immediate' | 'none' =>
          match.event.type === 'turn/end' ? 'immediate' : 'none',
      })
      ctx.effect(() => dispose, 'dsh-diff-review conversation definition')
    } catch (error) {
      console.error('dsh-diff-review: failed to register diff-review-tail conversation definition', error)
    }
  }

  if (betterSidebar !== undefined) {
    betterSidebar.registerTab({
      id: '@dsh-external/dsh-diff-review:review',
      title: '审阅',
      order: 90,
      single: true,
      icon: (size: number): ReactNode =>
        createElement('svg', { width: size, height: size, viewBox: '0 0 24 24', fill: 'none', 'aria-hidden': true },
          createElement('path', { d: 'M5 4h14v16H5V4Z', stroke: 'currentColor', strokeWidth: 1.7, strokeLinejoin: 'round' }),
          createElement('path', { d: 'M9 9h6M9 13h6', stroke: 'currentColor', strokeWidth: 1.7, strokeLinecap: 'round' }),
        ),
      component: ReviewSidebarTab,
    })
  }
}
